-- Generated by make_tenders_sql.py: do not edit by hand.
CREATE SCHEMA IF NOT EXISTS eprocure;

-- '28-May-2025 06:30 PM' or '28-May-2025' -> timestamp; anything else -> NULL
CREATE OR REPLACE FUNCTION eprocure.ts(t text) RETURNS timestamp LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  IF t IS NULL OR btrim(t) = '' THEN RETURN NULL; END IF;
  BEGIN RETURN to_timestamp(btrim(t), 'DD-Mon-YYYY HH12:MI AM')::timestamp; EXCEPTION WHEN others THEN NULL; END;
  BEGIN RETURN to_timestamp(btrim(t), 'DD-Mon-YYYY')::timestamp; EXCEPTION WHEN others THEN RETURN NULL; END;
END $$;

-- '65,870' -> 65870, 'NA' or '' -> NULL
CREATE OR REPLACE FUNCTION eprocure.num(t text) RETURNS numeric LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  RETURN NULLIF(regexp_replace(coalesce(t, ''), '[^0-9.]', '', 'g'), '')::numeric;
EXCEPTION WHEN others THEN RETURN NULL;
END $$;

-- dropped and recreated (not replaced) so new parser columns can sit before the window columns; nothing depends on this view
DROP VIEW IF EXISTS eprocure.tenders;
CREATE VIEW eprocure.tenders AS
SELECT
  r.record_id AS tender_id,
  r.data->>'org_id' AS org_id,
  r.data->>'org_name' AS org_name,
  r.data->'details'->'fields'->>'org_chain' AS org_chain,
  r.data->'details'->'fields'->>'tender_ref_no' AS tender_ref_no,
  r.data->'details'->'fields'->>'tender_title' AS tender_title,
  r.data->'details'->'fields'->>'stage' AS stage,
  r.data->'details'->'fields'->>'sno' AS sno,
  r.data->'details'->'fields'->>'view_link' AS view_link,
  r.data->'details'->'fields'->>'tender_type' AS tender_type,
  r.data->'details'->'fields'->>'form_of_contract' AS form_of_contract,
  r.data->'details'->'fields'->>'tender_category' AS tender_category,
  (r.data->'details'->'fields'->>'no_of_covers')::int AS no_of_covers,
  r.data->'details'->'fields'->>'payment_mode' AS payment_mode,
  r.data->'details'->'fields'->>'is_multi_currency_boq' AS is_multi_currency_boq,
  r.data->'details'->'fields'->>'is_multi_currency_fee' AS is_multi_currency_fee,
  r.data->'details'->'fields'->>'allow_two_stage_bidding' AS allow_two_stage_bidding,
  r.data->'details'->'fields'->>'withdrawal_allowed' AS withdrawal_allowed,
  r.data->'details'->'fields'->>'general_tech_eval_allowed' AS general_tech_eval_allowed,
  r.data->'details'->'fields'->>'itemwise_tech_eval_allowed' AS itemwise_tech_eval_allowed,
  eprocure.num(r.data->'details'->'fields'->>'tender_fee') AS tender_fee,
  r.data->'details'->'fields'->>'fee_payable_to' AS fee_payable_to,
  r.data->'details'->'fields'->>'fee_payable_at' AS fee_payable_at,
  r.data->'details'->'fields'->>'tender_fee_exemption_allowed' AS tender_fee_exemption_allowed,
  eprocure.num(r.data->'details'->'fields'->>'emd_amount') AS emd_amount,
  r.data->'details'->'fields'->>'emd_fee_type' AS emd_fee_type,
  eprocure.num(r.data->'details'->'fields'->>'emd_percentage') AS emd_percentage,
  r.data->'details'->'fields'->>'emd_exemption_allowed' AS emd_exemption_allowed,
  r.data->'details'->'fields'->>'emd_payable_to' AS emd_payable_to,
  r.data->'details'->'fields'->>'emd_payable_at' AS emd_payable_at,
  r.data->'details'->'fields'->>'work_description' AS work_description,
  r.data->'details'->'fields'->>'pre_qualification' AS pre_qualification,
  r.data->'details'->'fields'->>'iem_remarks' AS iem_remarks,
  eprocure.num(r.data->'details'->'fields'->>'tender_value') AS tender_value,
  r.data->'details'->'fields'->>'product_category' AS product_category,
  r.data->'details'->'fields'->>'sub_category' AS sub_category,
  r.data->'details'->'fields'->>'contract_type' AS contract_type,
  (r.data->'details'->'fields'->>'bid_validity_days')::int AS bid_validity_days,
  (r.data->'details'->'fields'->>'period_of_work_days')::int AS period_of_work_days,
  r.data->'details'->'fields'->>'location' AS location,
  r.data->'details'->'fields'->>'pincode' AS pincode,
  r.data->'details'->'fields'->>'pre_bid_meeting_place' AS pre_bid_meeting_place,
  r.data->'details'->'fields'->>'pre_bid_meeting_address' AS pre_bid_meeting_address,
  eprocure.ts(r.data->'details'->'fields'->>'pre_bid_meeting_date') AS pre_bid_meeting_at,
  r.data->'details'->'fields'->>'bid_opening_place' AS bid_opening_place,
  eprocure.ts(r.data->'details'->'fields'->>'published_date') AS published_at,
  eprocure.ts(r.data->'details'->'fields'->>'bid_opening_date') AS bid_opening_at,
  eprocure.ts(r.data->'details'->'fields'->>'bid_download_start_date') AS bid_download_start_at,
  eprocure.ts(r.data->'details'->'fields'->>'bid_download_end_date') AS bid_download_end_at,
  eprocure.ts(r.data->'details'->'fields'->>'clarification_start_date') AS clarification_start_at,
  eprocure.ts(r.data->'details'->'fields'->>'clarification_end_date') AS clarification_end_at,
  eprocure.ts(r.data->'details'->'fields'->>'bid_submission_start_date') AS bid_submission_start_at,
  eprocure.ts(r.data->'details'->'fields'->>'bid_submission_end_date') AS bid_submission_end_at,
  r.data->'details'->'fields'->>'tia_name' AS tia_name,
  r.data->'details'->'fields'->>'tia_address' AS tia_address,
  (r.data->'details'->'fields'->>'bids_count')::int AS bids_count,
  (r.data->'details'->'fields'->>'qualified_bids_count')::int AS qualified_bids_count,
  r.data->'details'->'fields'->>'winner_bidder_name' AS winner_bidder_name,
  eprocure.num(r.data->'details'->'fields'->>'awarded_value') AS awarded_value,
  eprocure.ts(r.data->'details'->'fields'->>'award_date') AS awarded_at,
  (r.data->'details'->'fields'->>'has_boq_chart')::int AS has_boq_chart,
  (r.data->'details'->'fields'->>'has_tech_summary')::int AS has_tech_summary,
  eprocure.ts(r.data->'details'->'fields'->>'financial_bid_opening_date') AS financial_bid_opening_at,
  eprocure.num(r.data->'details'->'fields'->>'contract_value_aoc_total') AS contract_value_aoc_total,
  r.data->'details'->'fields'->>'aoc_currency' AS aoc_currency,
  eprocure.num(r.data->'details'->'fields'->>'awarded_value_sum') AS awarded_value_sum,
  r.data->'details'->'fields'->'winners' AS winners,
  (r.data->'details'->'fields'->>'priced_bidders')::int AS priced_bidders,
  r.data->'details'->'fields'->>'l1_bidder_name' AS l1_bidder_name,
  eprocure.num(r.data->'details'->'fields'->>'l1_bid_value') AS l1_bid_value,
  r.data->'details'->'fields'->>'l1_rank_raw' AS l1_rank_raw,
  (r.data->'details'->'fields'->>'l1_inferred')::boolean AS l1_inferred,
  r.data->'details'->'fields'->'stage_done' AS stage_done,
  r.data->'details'->'fields'->>'last_stage_completed' AS last_stage_completed,
  r.data->'details'->'fields'->'date_flags' AS date_flags,
  r.data->'window'->>0 AS window_from,
  r.data->'window'->>1 AS window_to,
  r.data->'details'->>'pages_key' AS pages_key,
  r.data->'details'->'procurement_details' AS procurement_details,
  r.data->'details'->'outcomes' AS commercial_outcomes,
  r.data->'details'->>'parse_error' AS parse_error,
  r.scraped_at
FROM public.records r WHERE r.project = 'eprocure-tenders';

CREATE OR REPLACE VIEW eprocure.tender_bids AS
SELECT r.record_id AS tender_id, b->>'sno' AS sno, b->>'bid_number' AS bid_number, b->>'bidder_name' AS bidder_name,
       eprocure.ts(b->>'submitted_date') AS submitted_at, b->>'status' AS status, b->>'remarks' AS remarks,
       eprocure.ts(b->>'status_updated_on') AS status_updated_at
FROM public.records r, jsonb_array_elements(r.data->'details'->'bids') b WHERE r.project = 'eprocure-tenders';

CREATE OR REPLACE VIEW eprocure.tender_documents AS
SELECT r.record_id AS tender_id, d->>'name' AS name, d->>'kind' AS kind, d->>'status' AS status, d->>'reason' AS reason,
       (d->>'declared_bytes')::bigint AS declared_bytes, (d->>'bytes')::bigint AS bytes, d->>'content_type' AS content_type,
       d->>'sha256' AS sha256, d->>'key' AS storage_key
FROM public.records r, jsonb_array_elements(r.data->'details'->'documents') d WHERE r.project = 'eprocure-tenders';

-- tenders per organisation per date window, from the planning pass
CREATE OR REPLACE VIEW eprocure.plan AS
SELECT r.data->>'org_id' AS org_id, r.data->>'org_name' AS org_name, r.data->>'from_date' AS from_date, r.data->>'to_date' AS to_date,
       (r.data->>'count')::int AS tenders
FROM public.records r WHERE r.project = 'eprocure-plan';

